import{_ as e,o as r,c as l,a3 as s,j as t}from"./chunks/framework.Cc-oPviL.js";const x=JSON.parse('{"title":"01 · RAG 是什么：先查资料再回答","description":"","frontmatter":{},"headers":[],"relativePath":"ai/rag/01.md","filePath":"ai/rag/01.md"}'),i={name:"ai/rag/01.md"};function o(d,a,n,h,c,g){return r(),l("div",null,[...a[0]||(a[0]=[s('<h1 id="_01-·-rag-是什么-先查资料再回答" tabindex="-1">01 · RAG 是什么：先查资料再回答 <a class="header-anchor" href="#_01-·-rag-是什么-先查资料再回答" aria-label="Permalink to &quot;01 · RAG 是什么：先查资料再回答&quot;">​</a></h1><blockquote><p><strong>学完你能说出</strong>：</p><ul><li>RAG 的完整流程：离线建库（切块 → 向量化 → 入库）+ 在线问答（问题向量化 → 检索 → 拼提示词 → 生成）。</li><li>RAG 解决了大模型的哪三个问题。</li><li>RAG 和微调的区别，什么时候用哪个。</li></ul></blockquote><h2 id="先看地图" tabindex="-1">先看地图 <a class="header-anchor" href="#先看地图" aria-label="Permalink to &quot;先看地图&quot;">​</a></h2><p>大模型基础讲完了：模型会接龙（01）、会看上下文（02）、文字能变成向量（03）、提示词能引导它（04）。</p><p>把这四样拼起来，就是 <strong>RAG</strong>。本篇讲 4 个点：① 大模型直接用有什么问题 → ② RAG 的完整流程 → ③ 为什么这么设计 → ④ RAG vs 微调。</p><h2 id="一句话本质" tabindex="-1">一句话本质 <a class="header-anchor" href="#一句话本质" aria-label="Permalink to &quot;一句话本质&quot;">​</a></h2><p><strong>RAG（检索增强生成）= 回答之前，先从资料库里找出相关的几段，连同问题一起交给大模型，让它照着资料回答。</strong></p><h2 id="生活类比-开卷考试" tabindex="-1">生活类比：开卷考试 <a class="header-anchor" href="#生活类比-开卷考试" aria-label="Permalink to &quot;生活类比：开卷考试&quot;">​</a></h2><ul><li><strong>直接问大模型</strong> = 闭卷考试：全凭记忆，记不清就靠「感觉」编（幻觉）。</li><li><strong>RAG</strong> = 开卷考试：允许翻书，但只给你 <strong>3 页</strong>（上下文窗口有限），所以关键是<strong>先快速找到最相关的那 3 页</strong>。</li><li>找页的过程叫<strong>检索</strong>，看着这几页写答案的过程叫<strong>生成</strong>。</li></ul><h2 id="一步步看-「公司年假几天-」" tabindex="-1">一步步看：「公司年假几天？」 <a class="header-anchor" href="#一步步看-「公司年假几天-」" aria-label="Permalink to &quot;一步步看：「公司年假几天？」&quot;">​</a></h2>',10),t("figure",{class:"fig"},[t("span",{class:"fig-hint"},"← 左右滑动看完整图 →"),t("svg",{viewBox:"0 0 680 300",width:"100%",xmlns:"http://www.w3.org/2000/svg",role:"img","aria-label":"RAG 流程图"},[t("defs",null,[t("marker",{id:"arw-rag",viewBox:"0 0 10 10",markerWidth:"9",markerHeight:"9",refX:"8.5",refY:"5",markerUnits:"userSpaceOnUse",orient:"auto"},[t("path",{d:"M2 1.5 L8 5 L2 8.5",class:"f-line",fill:"none","stroke-linecap":"round","stroke-linejoin":"round"})])]),t("text",{class:"f-label",x:"20",y:"24"},"离线：提前建好资料库（只做一次，资料更新时再做）"),t("rect",{class:"f-box",x:"20",y:"36",width:"110",height:"52",rx:"8"}),t("text",{class:"f-title",x:"75.0",y:"58.0","text-anchor":"middle"},"原始文档"),t("text",{class:"f-label",x:"75.0",y:"76.0","text-anchor":"middle"},"PDF / 网页"),t("rect",{class:"f-box",x:"170",y:"36",width:"110",height:"52",rx:"8"}),t("text",{class:"f-title",x:"225.0",y:"58.0","text-anchor":"middle"},"切块"),t("text",{class:"f-label",x:"225.0",y:"76.0","text-anchor":"middle"},"每块约 500 字"),t("rect",{class:"f-box",x:"320",y:"36",width:"130",height:"52",rx:"8"}),t("text",{class:"f-title",x:"385.0",y:"58.0","text-anchor":"middle"},"Embedding"),t("text",{class:"f-label",x:"385.0",y:"76.0","text-anchor":"middle"},"文字 → 向量"),t("rect",{class:"f-box-alt",x:"490",y:"36",width:"170",height:"52",rx:"8"}),t("text",{class:"f-title",x:"575.0",y:"58.0","text-anchor":"middle"},"向量数据库"),t("text",{class:"f-label",x:"575.0",y:"76.0","text-anchor":"middle"},"存「向量 + 原文」"),t("path",{class:"f-line",d:"M130 62 H166","marker-end":"url(#arw-rag)"}),t("path",{class:"f-line",d:"M280 62 H316","marker-end":"url(#arw-rag)"}),t("path",{class:"f-line",d:"M450 62 H486","marker-end":"url(#arw-rag)"}),t("text",{class:"f-label",x:"20",y:"134"},"在线：每次提问都走一遍"),t("rect",{class:"f-box",x:"20",y:"148",width:"110",height:"52",rx:"8"}),t("text",{class:"f-title",x:"75.0",y:"170.0","text-anchor":"middle"},"用户问题"),t("text",{class:"f-label",x:"75.0",y:"188.0","text-anchor":"middle"},"「年假几天？」"),t("rect",{class:"f-box",x:"170",y:"148",width:"130",height:"52",rx:"8"}),t("text",{class:"f-title",x:"235.0",y:"170.0","text-anchor":"middle"},"Embedding"),t("text",{class:"f-label",x:"235.0",y:"188.0","text-anchor":"middle"},"问题 → 向量"),t("rect",{class:"f-box-hi",x:"340",y:"148",width:"130",height:"52",rx:"8"}),t("text",{class:"f-title",x:"405.0",y:"170.0","text-anchor":"middle"},"检索 Top-K"),t("text",{class:"f-label",x:"405.0",y:"188.0","text-anchor":"middle"},"找最像的 3 块"),t("rect",{class:"f-box",x:"510",y:"148",width:"150",height:"52",rx:"8"}),t("text",{class:"f-title",x:"585.0",y:"170.0","text-anchor":"middle"},"拼进提示词"),t("text",{class:"f-label",x:"585.0",y:"188.0","text-anchor":"middle"},"问题 + 3 块资料"),t("path",{class:"f-line",d:"M130 174 H166","marker-end":"url(#arw-rag)"}),t("path",{class:"f-line",d:"M300 174 H336","marker-end":"url(#arw-rag)"}),t("path",{class:"f-line",d:"M470 174 H506","marker-end":"url(#arw-rag)"}),t("path",{class:"f-line f-dash",d:"M575 88 V112 H405 V144","marker-end":"url(#arw-rag)"}),t("text",{class:"f-label",x:"414",y:"108"},"按向量相似度去库里找"),t("rect",{class:"f-box-hi",x:"510",y:"236",width:"150",height:"52",rx:"8"}),t("text",{class:"f-title",x:"585.0",y:"258.0","text-anchor":"middle"},"大模型回答"),t("text",{class:"f-label",x:"585.0",y:"276.0","text-anchor":"middle"},"「依据第 3 条：5 天」"),t("path",{class:"f-line-hi",d:"M585 200 V232","marker-end":"url(#arw-rag)"}),t("text",{class:"f-label",x:"20",y:"262"},"关键：模型不是「记住」了资料，"),t("text",{class:"f-label",x:"20",y:"280"},"而是每次回答前「现查现看」。")]),t("figcaption",{class:"fig-cap"},"RAG 分两段：离线把资料切块、转成向量存进库；在线把问题也转成向量，找出最相似的几块，和问题一起塞给大模型。模型的答案来自「这次塞进来的资料」，所以能引用、能更新，幻觉也更少。")],-1),s(`<p><strong>离线阶段（提前做好，资料更新时再做一次）：</strong></p><ol><li>收集资料：员工手册 PDF，共 50 页。</li><li><strong>切块</strong>：切成约 200 块，每块 500 字左右。</li><li><strong>向量化</strong>：每块用 Embedding 模型算出一个向量。</li><li><strong>入库</strong>：把「向量 + 原文 + 来源（第几页）」存进<strong>向量数据库</strong>。</li></ol><p><strong>在线阶段（每次提问都走一遍）：</strong></p><ol><li>用户问：「年假几天？」</li><li>问题也用<strong>同一个</strong> Embedding 模型转成向量。</li><li>在库里找余弦相似度最高的 3 块（<strong>Top-K</strong>，这里 K = 3）。比如找到「第 12 页：年假规定……」。</li><li>拼成提示词：</li></ol><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[system] 请只根据下面的资料回答；资料里没有就说不知道，并注明出处页码。</span></span>
<span class="line"><span>[资料1] (第12页) 员工入职满一年，享有带薪年假 5 天……</span></span>
<span class="line"><span>[资料2] ……</span></span>
<span class="line"><span>[user]   年假几天？</span></span></code></pre></div><ol start="5"><li>大模型回答：「入职满一年后有 5 天带薪年假（见第 12 页）。」</li></ol><h2 id="为什么这么设计" tabindex="-1">为什么这么设计 <a class="header-anchor" href="#为什么这么设计" aria-label="Permalink to &quot;为什么这么设计&quot;">​</a></h2><h3 id="为什么需要-rag-直接问大模型有什么问题" tabindex="-1">为什么需要 RAG？直接问大模型有什么问题？ <a class="header-anchor" href="#为什么需要-rag-直接问大模型有什么问题" aria-label="Permalink to &quot;为什么需要 RAG？直接问大模型有什么问题？&quot;">​</a></h3><p>大模型直接用，有三个问题：</p><table tabindex="0"><thead><tr><th>问题</th><th>例子</th><th>RAG 怎么解决</th></tr></thead><tbody><tr><td><strong>不知道私有资料</strong></td><td>你们公司的手册它没见过</td><td>现查现给</td></tr><tr><td><strong>知识过时</strong></td><td>训练数据有截止日期</td><td>资料库可以随时更新</td></tr><tr><td><strong>会编（幻觉）</strong></td><td>不知道时会编一个像样的答案</td><td>要求「只根据资料回答，并注明出处」</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">一句话答法</p><p>大模型不知道私有和最新的资料，还会编；RAG 在回答前先检索相关资料、拼进提示词，让答案有依据、可溯源、可更新。</p></div><h3 id="为什么要切块-不把整本手册塞进去" tabindex="-1">为什么要切块，不把整本手册塞进去？ <a class="header-anchor" href="#为什么要切块-不把整本手册塞进去" aria-label="Permalink to &quot;为什么要切块，不把整本手册塞进去？&quot;">​</a></h3><ul><li><strong>问题</strong>：整本手册可能有几十万字，超出上下文窗口；就算塞得下，成本高、速度慢，无关内容还会干扰模型。</li><li><strong>方案</strong>：切成小块，每次只取最相关的几块。</li><li><strong>好处</strong>：便宜、快，而且模型注意力集中在相关内容上。</li></ul><div class="tip custom-block"><p class="custom-block-title">一句话答法</p><p>上下文窗口有限、按 Token 计费，而且无关内容会干扰回答；切块后只取最相关的几块，又省又准。</p></div><h3 id="为什么提示词里要写「没有就说不知道」" tabindex="-1">为什么提示词里要写「没有就说不知道」？ <a class="header-anchor" href="#为什么提示词里要写「没有就说不知道」" aria-label="Permalink to &quot;为什么提示词里要写「没有就说不知道」？&quot;">​</a></h3><ul><li><strong>问题</strong>：检索不一定每次都能找到答案。找不到时，模型还是会照着「接龙」的习惯编一个。</li><li><strong>方案</strong>：在 system 里明确要求：只根据资料回答，资料里没有就说不知道，并注明出处。</li><li><strong>好处</strong>：降低幻觉；有出处，用户可以自己核对。</li></ul><div class="tip custom-block"><p class="custom-block-title">一句话答法</p><p>因为检索可能失败，必须约束模型「只依据资料、没有就承认」，再要求给出处，答案才可信、可核对。</p></div><h2 id="rag-vs-微调" tabindex="-1">RAG vs 微调 <a class="header-anchor" href="#rag-vs-微调" aria-label="Permalink to &quot;RAG vs 微调&quot;">​</a></h2><p><strong>微调（Fine-tuning）</strong>：用你的数据继续训练模型，改的是模型的<strong>参数</strong>。</p><table tabindex="0"><thead><tr><th></th><th>RAG</th><th>微调</th></tr></thead><tbody><tr><td>改的是什么</td><td>每次给的<strong>输入</strong></td><td>模型的<strong>参数</strong></td></tr><tr><td>适合</td><td>让模型知道<strong>新知识、私有资料</strong></td><td>让模型学会<strong>风格、格式、特定行为</strong></td></tr><tr><td>资料更新</td><td>改库就行，立刻生效</td><td>要重新训练</td></tr><tr><td>能否给出处</td><td>能</td><td>难</td></tr><tr><td>成本</td><td>低，起步快</td><td>需要数据和训练资源</td></tr></tbody></table><p><strong>类比</strong>：RAG 是<strong>给学生发参考书</strong>，微调是<strong>让学生上培训班</strong>。要他知道公司新制度，发手册（RAG）；要他养成特定的写作风格，上培训班（微调）。两者也可以一起用。</p><h2 id="英文术语拆解" tabindex="-1">英文术语拆解 <a class="header-anchor" href="#英文术语拆解" aria-label="Permalink to &quot;英文术语拆解&quot;">​</a></h2><table tabindex="0"><thead><tr><th>术语</th><th>拆开看</th><th>一句话意思</th></tr></thead><tbody><tr><td>RAG</td><td>Retrieval 检索 + Augmented 增强的 + Generation 生成</td><td>检索增强生成：先查资料，再生成回答</td></tr><tr><td>Chunk</td><td>块</td><td>文档切出来的一小段</td></tr><tr><td>Vector Database</td><td>vector 向量 + database 数据库</td><td>专门存向量、能快速找「最相似向量」的数据库</td></tr><tr><td>Top-K</td><td>top 最前面 + K 个</td><td>取相似度最高的 K 条</td></tr><tr><td>Retriever</td><td>retrieve 取回 + -er 「做…的东西」</td><td>检索器，负责找资料</td></tr><tr><td>Fine-tuning</td><td>fine 精细 + tuning 调节</td><td>微调：用自己的数据继续训练模型</td></tr><tr><td>Grounding</td><td>ground 地面、根据</td><td>让回答「落地」到给定资料上</td></tr></tbody></table><h2 id="面试怎么问" tabindex="-1">面试怎么问 <a class="header-anchor" href="#面试怎么问" aria-label="Permalink to &quot;面试怎么问&quot;">​</a></h2><p><strong>Q：讲一下 RAG 的完整流程。</strong></p><blockquote><p>离线：文档加载 → 清洗 → 切块 → 用 Embedding 模型向量化 → 存入向量库（同时存原文和元数据）。在线：问题向量化 → 在向量库中检索 Top-K 相似块（常配合关键词检索和重排）→ 把检索结果和问题拼成提示词 → 大模型生成回答，并附上出处。</p></blockquote><p><strong>Q：RAG 和微调怎么选？</strong></p><blockquote><p>补充知识、知识经常更新、需要出处的场景用 RAG；改变模型的输出风格、格式或特定领域的行为模式用微调。两者不互斥，可以先 RAG，效果不够再考虑微调。</p></blockquote><p><strong>Q：RAG 能完全消除幻觉吗？</strong></p><blockquote><p>不能。检索可能找错或找不到，模型也可能不忠实于资料。要靠提示约束（只依据资料、不知道就说）、提升检索质量（混合检索、重排）、回答附带出处，以及做忠实度评估来降低。</p></blockquote><h2 id="容易混的地方" tabindex="-1">容易混的地方 <a class="header-anchor" href="#容易混的地方" aria-label="Permalink to &quot;容易混的地方&quot;">​</a></h2><ul><li><strong>RAG 不会让模型「学会」资料</strong>：模型参数不变，每次都是现查现用。换一个问题，查到的就不一样。</li><li><strong>检索用的 Embedding 模型 ≠ 回答用的大模型</strong>：两个不同的模型，分工不同。</li><li><strong>K 不是越大越好</strong>：K 太大，无关内容会混进来、成本上升；太小可能漏掉答案。常见取 3–10，要实测。</li></ul><h2 id="和其他知识的连接" tabindex="-1">和其他知识的连接 <a class="header-anchor" href="#和其他知识的连接" aria-label="Permalink to &quot;和其他知识的连接&quot;">​</a></h2><ul><li><strong>← 来自</strong> <a href="/study-hub/ai/llm/03">Embedding</a>：检索就是比较向量相似度。</li><li><strong>← 来自</strong> <a href="/study-hub/ai/llm/04">Prompt 与采样参数</a>：把资料拼进提示词，并约束「只依据资料」。</li><li><strong>→ 影响</strong> <a href="/study-hub/ai/rag/02">切块与入库</a>、<a href="/study-hub/ai/rag/03">检索与重排</a>：流程里每一步的细节。</li><li><strong>→ 影响</strong> <a href="/study-hub/ai/agent/01">Agent 是什么</a>：「检索」可以作为 Agent 的一个工具。</li></ul><h2 id="自测-3-问" tabindex="-1">自测 3 问 <a class="header-anchor" href="#自测-3-问" aria-label="Permalink to &quot;自测 3 问&quot;">​</a></h2><p><strong>Q1：用「开卷考试」类比讲清 RAG。</strong></p><details class="details custom-block"><summary>点开看答案</summary><p>直接问大模型像闭卷考试，记不清就编；RAG 像开卷考试，但只能带几页纸，所以先<strong>检索</strong>出最相关的几页，再看着这几页<strong>生成</strong>答案。</p></details><p><strong>Q2：RAG 解决了大模型的哪三个问题？</strong></p><details class="details custom-block"><summary>点开看答案</summary><p>① 不知道私有资料；② 知识过时（训练有截止日期）；③ 容易幻觉。RAG 现查现给资料，库可随时更新，并约束模型只依据资料回答、注明出处。</p></details><p><strong>Q3：要让模型知道公司最新的报销制度，用 RAG 还是微调？为什么？</strong></p><details class="details custom-block"><summary>点开看答案</summary><p><strong>RAG</strong>。这是补充知识，而且制度会变；RAG 改库就生效，还能给出处。微调更适合改变风格和行为，更新知识要重新训练，成本高。</p></details><h2 id="✅-验收清单" tabindex="-1">✅ 验收清单 <a class="header-anchor" href="#✅-验收清单" aria-label="Permalink to &quot;✅ 验收清单&quot;">​</a></h2><ul><li class="sh-task-item"><input type="checkbox" class="sh-task" data-i="0"> 能不看图画出 RAG 的离线、在线两段流程</li><li class="sh-task-item"><input type="checkbox" class="sh-task" data-i="1"> 能说出 RAG 解决的三个问题，并各举一个例子</li><li class="sh-task-item"><input type="checkbox" class="sh-task" data-i="2"> 能讲清「为什么要切块」「为什么要求没有就说不知道」（问题 → 方案 → 好处）</li><li class="sh-task-item"><input type="checkbox" class="sh-task" data-i="3"> 能用一张表对比 RAG 和微调，并说出各自适合的场景</li><li class="sh-task-item"><input type="checkbox" class="sh-task" data-i="4"> 能说出 RAG 不能完全消除幻觉的原因</li></ul><h2 id="下一步该懂什么" tabindex="-1">下一步该懂什么 <a class="header-anchor" href="#下一步该懂什么" aria-label="Permalink to &quot;下一步该懂什么&quot;">​</a></h2><ul><li>切块切多大、怎么切？→ <a href="/study-hub/ai/rag/02">切块与入库</a></li><li>你 5 月做过的项目（<code>E:\\Desktop\\1</code>，FastAPI + Chroma）就是一个 RAG。学完本模块，可以回头对照它的 <code>rag.py</code>。</li></ul>`,45)])])}const u=e(i,[["render",o]]);export{x as __pageData,u as default};
